import{z as s,x as l,o as e,c as o,q as A,j as n,D as a,d as t,s as r,S as i}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"复现一篇因子研究","description":"","frontmatter":{"title":"复现一篇因子研究","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/fz-replication-exercise.md","filePath":"quant/fz-replication-exercise.md","lastUpdated":1791063341000}'),p={name:"quant/fz-replication-exercise.md"};function d(m,E,h,u,c,F){const B=l("Mermaid");return e(),o("div",null,[E[2]||(E[2]=A('<h1 id="复现一篇因子研究" tabindex="-1">复现一篇因子研究 <a class="header-anchor" href="#复现一篇因子研究" aria-label="Permalink to &quot;复现一篇因子研究&quot;">​</a></h1><div class="epigraph"><p>复现的目标不是得到同一个数，而是用原文的规范得到接近的数，并知道每个偏差从哪个参数进来——符号稳住的扰动是约定，符号翻转的扰动是机制。</p><footer>—— 据 Fama &amp; French, Journal of Financial Economics, 1993；Hou, Xue &amp; Zhang, Review of Financial Studies, 2020；Jensen, Kelly &amp; Pedersen, Journal of Finance, 2023 整理</footer></div><p><a href="/quant/fz-reporting-standard">上一课</a>把报告骨架写死；本课把骨架用一遍：完整复现一篇经典——Fama–French 1993 的 HML——从数据到主表，再做扰动测试。文献里正有一场现实的争论：Hou–Xue–Zhang 2020 重做数百个异象，发现大半在他们的规范下消失；Jensen–Kelly–Pedersen 2023 则争辩相当一部分差异来自规范选择而非数据挖掘。孰是孰非，需要亲手看过数字随约定移动才有判断力——本课的目标就是这个经验，不是又一篇 HML 综述。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>复现有正确与错误两种失败方式。错误的方式：跑出一个数与原文不同，宣布「复现不了」，或反过来硬调参数凑数。正确的方式：把差异定位到参数——分位点口径、数据 vintage、退市处理、加权方案，逐一归因。HML 是最好的练习对象：它足够简单（六个组合的线性组合），又足够多坑（会计数据滞后、负账面权益、NYSE 分位点、年度重构），这些坑在自研因子上原样出现。缺口是把「复现」从口号变成一套有输出的流程：约定对照表、主表、扰动表、判定。</p><h3 id="流程" tabindex="-1">流程 <a class="header-anchor" href="#流程" aria-label="Permalink to &quot;流程&quot;">​</a></h3><p><span class="marginnote">FF 1993 的几条硬约定：每年 6 月末按当月市值分组；B/M 用上一财年账面值且至少滞后六个月；分位点取自 NYSE 股票；负账面权益的股票不参与 B/M 排序但留在规模组。换掉任何一条都会移动 HML 的均值——复现报告的第一张表应是约定对照表。</span></p><p>第一步，冻结规范：从原文抄下每条约定，列成对照表；数据侧确认 <a href="/quant/crsp-compustat">CRSP–Compustat</a> 式的跨库对齐、会计数据的 <a href="/quant/pit-fundamentals">PIT 与滞后</a>、退市收益是否计入（<a href="/quant/survivorship-bias">幸存者偏差</a>）。第二步，主表：六个市值加权组合的月度收益，HML 等于两个价值组合的平均减两个成长组合的平均，年度重构；对照原文的量级与 t。第三步，扰动表：一次只动一个约定——等权替代市值加权、年度重构改月度、分位点改全市场、去掉退市收益——记录每个扰动的方向与幅度。第四步，判定与归档：区分「只动水平的扰动」与「翻转符号的扰动」，按上一课的骨架归档复现包。</p>',8)),(e(),n(i,null,{default:a(()=>[r(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20P0%5B%22%E9%80%89%E5%AE%9A%E6%96%87%E7%8C%AE%E4%B8%8E%E5%8E%9F%E6%96%87%E8%A7%84%E8%8C%83%22%5D%20--%3E%20P1%5B%22%E5%86%BB%E7%BB%93%E7%BA%A6%E5%AE%9A%E5%AF%B9%E7%85%A7%E8%A1%A8%22%5D%0A%20%20P1%20--%3E%20P2%5B%22%E6%95%B0%E6%8D%AE%EF%BC%9APIT%2F%E6%BB%9E%E5%90%8E%2F%E9%80%80%E5%B8%82%E5%A4%84%E7%90%86%22%5D%0A%20%20P2%20--%3E%20P3%5B%22%E4%B8%BB%E8%A1%A8%EF%BC%9A%E5%85%AD%E7%BB%84%E5%90%88%E4%B8%8E%20HML%22%5D%0A%20%20P3%20--%3E%20P4%5B%22%E5%AF%B9%E7%85%A7%E5%8E%9F%E6%96%87%E9%87%8F%E7%BA%A7%E4%B8%8E%20t%22%5D%0A%20%20P4%20--%3E%20P5%5B%22%E6%89%B0%E5%8A%A8%EF%BC%9A%E4%B8%80%E6%AC%A1%E5%8A%A8%E4%B8%80%E4%B8%AA%E7%BA%A6%E5%AE%9A%22%5D%0A%20%20P5%20--%3E%20P6%7B%22%E5%88%A4%E5%AE%9A%22%7D%0A%20%20P6%20--%3E%7C%E5%8F%AA%E5%8A%A8%E6%B0%B4%E5%B9%B3%7C%20OK%5B%22%E7%BA%A6%E5%AE%9A%E5%B7%AE%E5%BC%82%EF%BC%8C%E8%AE%B0%E5%BD%95%E5%BD%92%E6%A1%A3%22%5D%0A%20%20P6%20--%3E%7C%E7%AC%A6%E5%8F%B7%E7%BF%BB%E8%BD%AC%7C%20WARN%5B%22%E6%9C%BA%E5%88%B6%E6%95%8F%E6%84%9F%EF%BC%8C%E5%86%99%E5%85%A5%E8%BE%B9%E7%95%8C%22%5D%0A%20%20OK%20--%3E%20P7%5B%22%E5%A4%8D%E7%8E%B0%E5%8C%85%EF%BC%9A%E4%BB%A3%E7%A0%81%2B%E5%BF%AB%E7%85%A7%2B%E5%81%8F%E5%B7%AE%E6%B8%85%E5%8D%95%22%5D%0A%20%20WARN%20--%3E%20P7%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>扰动表怎么读是这个练习的方法论核心。</p><p><span class="marginnote">「再平衡红利」的术语翻译：等权组合每月把涨多的卖一点、涨少的买一点，相当于系统性地高抛低吸——这部分收益来自构造方式本身，不是价值溢价。类比：篮子里两只基金各放一半，涨完不再平衡的 vs 每月再平衡的，长期收益路径完全不同；你以为是「价值在赚钱」，可能只是这个机械操作在赚钱。</span>等权替代市值加权，HML 通常上升——再平衡红利与小盘暴露混了进来，这是「构造混入别的溢价」的直接体验。去掉退市收益，价值端（常有退市股）被幸存者偏差抬高，这是数据处理的机制。年度重构改月度，换手与成本大增，成本后溢价明显缩水，这是持有期的机制。多数扰动移动水平但不翻转符号——「价值组合跑赢成长组合」在广泛的约定下稳住。这正是「衰减不等于死亡」的同族判断：稳健性有程度之分，复现把程度量化。翻转符号的扰动要单独写进边界：它标记了结论真正依赖的机制假设。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么亲手复现不可替代？参数的现实含义只有在数字移动时才被看见：读十遍「NYSE 分位点」，不如看一次换成分位点后 HML 掉了多少。</p><p><span class="marginnote">「符号稳住的是约定，符号翻转的是机制」可以类比工程里的敏感性分析：改外壳颜色不影响车能开（约定），换掉传动轴方向车就倒退（机制）。复现给你的不是「数字像不像」的印象，而是这张「哪个旋钮连着引擎」的清单——以后自己设计因子时，先保护连着引擎的旋钮。</span></p>',6)),(e(),n(i,null,{default:a(()=>[r(B,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E6%89%B0%E5%8A%A8%E8%A1%A8%EF%BC%9A%E4%B8%80%E6%AC%A1%E5%8F%AA%E5%8A%A8%E4%B8%80%E6%9D%A1%E7%BA%A6%E5%AE%9A%22%5D%20--%3E%20W1%5B%22%E7%AD%89%E6%9D%83%E6%9B%BF%E4%BB%A3%E5%B8%82%E5%80%BC%E5%8A%A0%E6%9D%83%22%5D%0A%20%20P%20--%3E%20W2%5B%22%E5%8E%BB%E6%8E%89%E9%80%80%E5%B8%82%E6%94%B6%E7%9B%8A%22%5D%0A%20%20P%20--%3E%20W3%5B%22%E5%B9%B4%E5%BA%A6%E9%87%8D%E6%9E%84%E6%94%B9%E6%9C%88%E5%BA%A6%22%5D%0A%20%20W1%20--%3E%20M1%5B%22%E6%B7%B7%E5%85%A5%E5%86%8D%E5%B9%B3%E8%A1%A1%E7%BA%A2%E5%88%A9%E4%B8%8E%E5%B0%8F%E7%9B%98%E6%9A%B4%E9%9C%B2%22%5D%0A%20%20W2%20--%3E%20M2%5B%22%E4%BB%B7%E5%80%BC%E7%AB%AF%E5%B9%B8%E5%AD%98%E8%80%85%E5%81%8F%E5%B7%AE%22%5D%0A%20%20W3%20--%3E%20M3%5B%22%E6%8D%A2%E6%89%8B%E4%B8%8E%E6%88%90%E6%9C%AC%E4%B8%8A%E5%8D%87%22%5D%0A%20%20M1%20--%3E%20L%5B%22%E6%B0%B4%E5%B9%B3%E7%A7%BB%E5%8A%A8%E4%B8%BA%E4%B8%BB%EF%BC%9A%E7%AC%A6%E5%8F%B7%E7%A8%B3%E4%BD%8F%22%5D%0A%20%20M2%20--%3E%20L%0A%20%20M3%20--%3E%20L%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<p>复现还校准对文献的信任：做过一次就知道，原文与复现的差异大多能被约定对照表解释——这是 Jensen–Kelly–Pedersen 论证「争论大半是规范差异」的微观基础；同时你也亲眼看到某些扰动下结论翻转——这是 Hou–Xue–Zhang 警告的内容。两种文献立场是同一张扰动表上的不同区域。复现训练的最后一块是归档：对照表、扰动表与偏差清单进包，接手的人从你的边界继续。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课复现的是构造与描述统计，不重做定价检验——GRS 与截面风险价格的推断见 <a href="/quant/grs-test">GRS 检验</a>与 <a href="/quant/fama-macbeth">Fama–MacBeth</a>。跨供应商与跨市场的复现（会计口径、制度差异）会引入原文不存在的偏差，属于另立规范的情形。样本期与原文不同，量级必然有差——复现比较的是「同一约定下的量级区间」，不是逐月吻合。</p><p><span class="marginnote">常见误区：跑出来的 HML 与原文差了 0.3 个百分点年化，就宣布「复现失败」或反过来偷偷调参数凑近原文。正确动作是查约定对照表：样本期错位、数据供应商修正、退市处理不同，任何一条都能解释这个量级的差异。复现的目标是「每个偏差知道从哪个参数进来」，不是小数点后两位一致。</span>复现一篇是为了建立能力；流程的价值在复现自研因子时兑现。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>复现的输出是四件套：约定对照表、主表、扰动表、判定与归档。</li><li>一次只动一个约定，区分「只动水平」与「翻转符号」两类扰动。</li><li>等权、退市、重构频率各自混入已知的机制：红利、幸存者、换手成本。</li><li>原文与复现的差异大多能被约定解释——扰动表是「规范差异与数据挖掘」之争的微观基础。</li><li>出处：Fama &amp; French, <em>JFE</em>, 1993；Hou, Xue &amp; Zhang, <em>RFS</em>, 2020；Jensen, Kelly &amp; Pedersen, <em>JF</em>, 2023。</li></ul>',6))])}const P=s(p,[["render",d]]);export{C as __pageData,P as default};
